import{_ as i,o as e,c as t,a2 as a}from"./chunks/framework.CdvW4CUT.js";const h=JSON.parse('{"title":"畫作系統","description":"玩家可以購買伺服玩家蓋的地圖畫，或從販售的畫作獲取收益。","frontmatter":{"title":"畫作系統","description":"玩家可以購買伺服玩家蓋的地圖畫，或從販售的畫作獲取收益。"},"headers":[],"relativePath":"feature/painting/index.md","filePath":"feature/painting.md"}'),o={name:"feature/painting/index.md"};function c(r,l,d,s,u,p){return e(),t("div",null,[...l[0]||(l[0]=[a('<h1 id="畫作系統" tabindex="-1">畫作系統 <a class="header-anchor" href="#畫作系統" aria-label="Permalink to &quot;畫作系統&quot;">​</a></h1><h2 id="查詢畫作-maplist" tabindex="-1">查詢畫作 <code>/maplist</code> <a class="header-anchor" href="#查詢畫作-maplist" aria-label="Permalink to &quot;查詢畫作 `/maplist`&quot;">​</a></h2><img src="https://i.imgur.com/3P8yyyN.png" style="width:60%;"><ul><li><code>/maplist &lt;玩家ID&gt;</code><b>查詢指定玩家的畫作</b></li><li><code>/maplist &lt;#標籤&gt;</code> <b>查詢指定標籤的畫作</b></li><li><code>/maplist !</code> <b>查詢最新同步的10張的畫作</b></li><li>其中每幅畫的格式皆為：<code>畫作ID 名稱 張數 價格 預覽 美術公園展示</code><ul><li><b>畫作ID：</b>畫作的ID，數字格式，即該畫作的代號，大部分時候都可以用此ID查詢畫作</li><li><b>名稱：</b>畫作的名稱，作者自取</li><li><b>張數：</b>該幅畫作的張數大小(有幾張地圖)</li><li><b>價格：</b>該畫作的價格，顯示未設定可能代表絕版或非公開販售，有興趣請自行詢問作者 <ul><li>點擊價格按鈕可以購買指定畫作</li></ul></li><li><b>預覽：</b>綠色可點擊預覽；黃色為尚未上傳圖庫無法預覽；紅色為R18畫作不可直接預覽，或預覽失敗；作者可自行設定是否允許他人預覽</li><li><b>美術公園展示：</b>代表該畫作有在伺服美術公園展示，點擊可傳送 <ul><li>僅當您在大廳服使用此指令才會顯示美術公園按鈕</li></ul></li></ul></li></ul><h2 id="購買畫作-map-畫作id" tabindex="-1">購買畫作 <code>/map &lt;畫作ID&gt;</code> <a class="header-anchor" href="#購買畫作-map-畫作id" aria-label="Permalink to &quot;購買畫作 `/map &lt;畫作ID&gt;`&quot;">​</a></h2><ul><li>若你知道特定畫作的ID，輸入這個指令可以購買指定畫作</li><li>藍色字為畫作標籤，由伺服方為您進行分類，若有分類錯誤可以使用<a href="/discord/customer_service/">客服系統</a>與我們回報!</li></ul><img src="https://i.imgur.com/tHBXzIp.png" style="width:60%;"><div class="tip custom-block"><p class="custom-block-title">便利功能</p><p>若你身上有空的界伏盒(沒有顏色的)，且畫作大於9張時，會優先放在盒子裡</p></div><h2 id="作者用指令" tabindex="-1">作者用指令 <a class="header-anchor" href="#作者用指令" aria-label="Permalink to &quot;作者用指令&quot;">​</a></h2><p>針對作者有一些販售與介紹等功能，可以在畫作販售時使用以下指令</p><ul><li>作者自己輸入<code>/maplist</code>後，點選要畫作即可使用以下設定(等同於<code>/map &lt;畫作ID&gt;</code>)</li><li>以下會有四個按鈕可以點擊並設定<br><img src="https://i.imgur.com/VjOD1nq.png" style="width:60%;"></li></ul><h3 id="設定價格" tabindex="-1">設定價格 <a class="header-anchor" href="#設定價格" aria-label="Permalink to &quot;設定價格&quot;">​</a></h3><ul><li><code>/mapset &lt;畫作ID&gt; price &lt;要設定的價格&gt;</code> 設定畫作價格 <ul><li>輸入這個指令可以設定自己名下指定畫作的價格</li></ul></li><li><code>/mapset &lt;畫作ID&gt; price clear</code> 清除畫作價格 <ul><li>若你沒有設定價格，其他玩家將無法購買您的畫作(可用於限購處理)</li></ul></li><li>其他說明 <ul><li>畫作價格最低 : 最低設定為單張6元，若你的畫作有12張地圖，則最低價格需設定為6*12=72元或以上</li><li>販售抽成手續費 : 為每張地圖酌收5元手續費，若你的畫作有12張地圖，設定販售價格為100元，你可以拿到100-5*12=40元收益</li></ul></li></ul><h3 id="設定存貨-畫作限購" tabindex="-1">設定存貨(畫作限購) <a class="header-anchor" href="#設定存貨-畫作限購" aria-label="Permalink to &quot;設定存貨(畫作限購)&quot;">​</a></h3><ul><li><code>/mapset &lt;畫作ID&gt; stock</code> 查看目前剩餘存貨</li><li><code>/mapset &lt;畫作ID&gt; stock set &lt;數字&gt;</code> 設定存貨數量 可以自由控管要販售幾張畫作，這對於想設計限量畫作販售的作者有很大幫助</li><li>可隨時可自由調整剩餘存貨(不用支付遊戲幣)</li><li>預設為99999套，若作者想販售且不限制的話，設定價格即可 <ul><li>若要販售但又不想無限制售出，請同時設定價格與存貨數量</li></ul></li><li>賣出一套即-1，當存貨=0後，玩家即無法購買，直到作者重新設定存貨</li></ul><h3 id="設定預覽" tabindex="-1">設定預覽 <a class="header-anchor" href="#設定預覽" aria-label="Permalink to &quot;設定預覽&quot;">​</a></h3><p>可以設定能不能讓玩家預覽畫作(打開外部圖片網站預覽)</p><ul><li><code>/mapset &lt;畫作ID&gt; exhibit true</code></li><li><code>/mapset &lt;畫作ID&gt; exhibit false</code></li></ul><h3 id="設定畫作敘述" tabindex="-1">設定畫作敘述 <a class="header-anchor" href="#設定畫作敘述" aria-label="Permalink to &quot;設定畫作敘述&quot;">​</a></h3><p>作者可以對自己的畫作增加自訂的介紹囉~提供作者介紹畫作的用途 <img src="https://i.imgur.com/2ANtBwe.png" style="width:60%;"></p><ul><li>畫作介紹支援<u>顏色與格式代碼</u>，也<u>支援URL網址處理</u></li><li>訊息長度最多70個字(非基本拉丁文/符號/空格 的文字，以2個字計算)</li><li><code>/mapset &lt;畫ID&gt; desc</code> 查看目前介紹</li><li><code>/mapset &lt;畫ID&gt; desc set &lt;介紹&gt;</code> 設定介紹</li><li><code>/mapset &lt;畫ID&gt; desc clear</code> 清除介紹</li></ul><h3 id="其他指令" tabindex="-1">其他指令 <a class="header-anchor" href="#其他指令" aria-label="Permalink to &quot;其他指令&quot;">​</a></h3><ul><li><code>/mapreceive</code><b>領取畫作收益</b><ul><li>輸入這個指令可以領取畫作售出的收益，其中會扣除每張地圖5元的成本</li></ul></li><li><code>/mapconvert</code><b>畫作轉換</b><ul><li>當<a href="/apply/form_paint/">畫作同步</a>完成後，可以手持未同步的地圖輸入該指令轉換成同步的畫作<br> 其中手持的地圖需與申請同步的地圖相同ID才能成功轉換</li></ul></li></ul><h2 id="建立畫作告示牌" tabindex="-1">建立畫作告示牌 <a class="header-anchor" href="#建立畫作告示牌" aria-label="Permalink to &quot;建立畫作告示牌&quot;">​</a></h2><p>建立跟美術館一樣，可以右鍵購買畫作的告示牌<br><b>設定方式：</b>放置告示牌，第一行輸入[畫作購買]，第二行輸入畫作ID，第三行輸入額外想打的字(可選)<br><img src="https://i.imgur.com/KH1rOIp.png" style="width:60%;"></p><ul><li>也可以設定為標籤或作者查詢，點擊後可查詢畫作列表(等同輸入<code>/maplist &lt;標籤或作者&gt;</code>)</li><li>標籤查詢方式 : 告示牌第二行輸入 <code>#標籤名稱</code></li><li>作者查詢方式 : 告示牌第二行輸入 <code>@作者名稱</code><br><img src="https://i.imgur.com/GOe6idQ.png" style="width:30%;"><img src="https://i.imgur.com/XFsBmvm.png" style="width:30%;"></li></ul>',26)])])}const n=i(o,[["render",c]]);export{h as __pageData,n as default};
